{{ config(tags=["source_idrc"]) }}

with source as (

    select * from {{ source('idrc', 'funding_opportunities') }}

),

records as (

    select
        payload as record,
        _batch_id::text as bronze_batch_id,
        _record_hash as bronze_record_hash,
        _landing_uri as bronze_landing_uri,
        _ingested_at as bronze_ingested_at
    from source

)

select
    (record ->> 'call_slug')::text as call_slug,
    (record ->> 'source_url')::text as source_url,
    (record ->> 'node_id')::text as node_id,
    (record ->> 'title')::text as title,
    (record ->> 'status')::text as status,
    (record ->> 'call_type')::text as call_type,
    (record ->> 'deadline')::timestamptz as deadline,
    (record ->> 'program')::text as program,
    (record ->> 'duration')::text as duration,
    (record ->> 'topic')::text as topic,
    (record ->> 'funded_by')::text as funded_by,
    (record ->> 'budget')::text as budget,
    (record ->> 'award_type')::text as award_type,
    (record ->> 'description_text')::text as description_text,
    (record ->> 'feed_published_at')::timestamptz as feed_published_at,
    (record ->> 'extraction_path')::text as extraction_path,
    (record ->> 'retrieved_at')::timestamptz as retrieved_at,
    bronze_batch_id,
    bronze_record_hash,
    bronze_landing_uri,
    bronze_ingested_at
from records
